(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*20+Math.cos(y*0.022-t*0.18)*15;
  const w1y = Math.cos(y*0.02-t*0.22)*18+Math.sin(x*0.016+t*0.3)*12;
