  const w2y = Math.cos(y*0.032+t*0.38)*7+Math.sin(x*0.028-t*0.32)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.5)*120,80+Math.cos(t*0.35)*60,0.07,2.1,1.0],
    [320+Math.cos(t*0.45)*110,160+Math.sin(t*0.6)*70,0.09,1.8,0.9],
    [240+Math.sin(t*0.28+2)*160,120+Math.cos(t*0.42+1)*100,0.055,2.5,1.1],
    [100+Math.cos(t*0.7+1)*90,180+Math.sin(t*0.55+3)*70,0.11,1.6,0.85],
    [380+Math.sin(t*0.38+4)*100,50+Math.cos(t*0.8+2)*80,0.065,2.8,1.05],
    [240+Math.cos(t*0.32+5)*130,200+Math.sin(t*0.48)*90,0.08,2.0,0.95],
    [60+Math.sin(t*0.6+3)*70,40+Math.cos(t*0.5+4)*50,0.13,1.4,0.8]
