    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const aw=Math.sin(d*f-t*sp)*amp,iw=Math.sin(d*f*0.65+t*sp*0.55+1.7)*amp;
    waves.push([aw,iw]);aS+=aw;iS+=iw;
  }
  for(let i=0;i<n;i++)for(let j=i+1;j<n;j++)cross+=waves[i][0]*waves[j][1]*0.15;
  aS/=n;iS/=n;cross/=(n*(n-1)/2);
  const bg1=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0))/2;
  const bg2=(Math.sin(sx*0.06-sy*0.05+t*1.5)+Math.sin(sx*0.045+sy*0.055-t*1.8))/2;
  const bg3=Math.sin((sx+sy)*0.11+t*2.2)*0.3+Math.sin((sx-sy)*0.09-t*1.7)*0.3;
  const bg=bg1*0.5+bg2*0.3+bg3*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
