  const sp3=Math.sin(d2*0.055+a2*2.5-t*1.8)*0.3;
  const feed=aS-iS*0.65+bg*0.25+spiral+sp3+cross;
  const reaction=Math.tanh(feed*2.0);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t*0.8)*0.5+Math.sin(sx*0.18-sy*0.12+t*0.6)*0.3)*1.3)*0.25;
  const fine=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.25-t*2.5)*0.08;
  const blend=reaction*0.65+cell*0.2+fine;
  const v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,52,82],[18,105,115],[45,158,135],[180,185,70],[225,175,55],[220,120,60],[195,75,75],[155,55,90],[85,30,75],[35,15,58],[6,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.72?1.12+(Math.abs(reaction)-0.72)*0.5:1.0;
  const chroma=1.0+cross*0.15;
  const vig=1.0-Math.sqrt((x-cx)**2+(y-cy)**2)/380*0.15;
