    Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*m))|0,
    Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*m*(2.0-chroma)))|0
  ];
}
